public class MainActivity extends Activity{SharedPreferences p;String[][]r={{"Carrera de la Mujer por la Igualdad","Córdoba"},{"XXI Ruta del Aceite","La Victoria"},{"Memorial Joaquín Sánchez","La Carlota"},{"XXI Legua Villa de Fernán Núñez","Fernán Núñez"},{"Ruta de la Miel","Hornachuelos"},{"Carrera Nocturna de Alcolea","Alcolea"},{"C.P. Peñarroya-Pueblonuevo","Peñarroya-Pueblonuevo"},{"C.P. Ciudad de Aguilar","Aguilar de la Frontera"}};TextView t(String s,int z){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setPadding(12,6,12,6);return v;}public void onCreate(Bundle b){super.onCreate(b);p=getSharedPreferences("hugo",0);draw();}void draw(){ScrollView s=new ScrollView(this);LinearLayout a=new LinearLayout(this);a.setOrientation(LinearLayout.VERTICAL);a.setPadding(18,18,18,30);s.addView(a);TextView h=t("HUGO RUNNING",28);h.setTextColor(Color.rgb(21,101,192));a.addView(h);a.addView(t("Carreras infantiles - Córdoba y alrededores",16));for(int i=0;i<r.length;i++){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(16,16,16,16);TextView n=t(r[i][0],20);n.setTextColor(Color.rgb(13,71,161));c.addView(n);c.addView(t("Lugar: "+r[i][1]+" | Fecha: Pendiente de verificación",15));c.addView(t("Hugo: 8-9 años | Distancia: Pendiente de reglamento",15));c.addView(t("Hora infantil: Pendiente | Dorsal: Pendiente de publicación",15));boolean y=p.getBoolean("r"+i,false);Button q=new Button(this);q.setText(y?"HUGO APUNTADO":"HUGO NO APUNTADO");final int k=i;q.setOnClickListener(v->{boolean x=!p.getBoolean("r"+k,false);p.edit().putBoolean("r"+k,x).apply();q.setText(x?"HUGO APUNTADO":"HUGO NO APUNTADO");});c.addView(q);a.addView(c);}setContentView(s);}}
